<style lang="scss" scoped src="./tabs.scss"></style>

<template>
  <div class="Tabs">
    <div class="Tabs__tabs" role="tablist">
      <button
        v-for="(tab, index) in tabs"
        :aria-controls="`panel-${index}`"
        :aria-selected="selectedIndex === index ? 'true' : 'false'"
        :class="[
          'Tabs__tab',
          { 'Tabs__tab--selected': selectedIndex === index }
        ]"
        :key="tab.title"
        role="tab"
        @click="selectTab(index)"
      >
        {{ tab.title }}
      </button>
    </div>
    <div aria-expanded="true" role="panel">
      <slot />
    </div>
  </div>
</template>

<script>
export default {
  props: {
    defaultTabIndex: {
      type: Number,
      default: 0
    }
  },
  data() {
    return {
      tabs: [],
      selectedIndex: 0
    };
  },
  watch: {
    defaultTabIndex: function() {
      this.selectTab(this.defaultTabIndex);
    }
  },
  created() {
    // initialize `this.tabs` with the array of `<Tab />` components
    this.tabs = this.$children;
  },
  mounted() {
    // select the initially opened tab based on the prop on mount
    this.selectTab(this.defaultTabIndex);
  },
  methods: {
    selectTab(i) {
      if (i < 0 || i > this.tabs.length - 1) {
        console.error(
          `Tried to access nonexistent tab index ${i}. Opening tab index 0 by default.`
        );

        i = 0;
      }

      this.selectedIndex = i;

      // sets the active tab given the tab index
      this.tabs.forEach((tab, index) => {
        tab.isActive = index === i;
      });

      // emits a tabSelected event with the tab index and title
      this.$emit("tabSelected", {
        index: i,
        title: this.tabs[i].title
      });
    }
  }
};
</script>
